import pandas as pd

def inspect_excel(file_path):
    print(f"--- Inspecting {file_path} ---")
    try:
        # Try reading without header first to see the layout
        if file_path.endswith('.xls'):
            df = pd.read_excel(file_path, engine='xlrd', header=None, nrows=20)
        else:
            df = pd.read_excel(file_path, engine='openpyxl', header=None, nrows=20)
        print(df)
    except Exception as e:
        print(f"Error reading {file_path}: {e}")
    print("\n")

inspect_excel('ERP-2025-table10.xls')
inspect_excel('ERP-2025-table12.xls')
inspect_excel('CPI.xlsx')

