import pandas as pd

def print_headers(file_path):
    print(f"--- Headers of {file_path} ---")
    if file_path.endswith('.xls'):
        df = pd.read_excel(file_path, engine='xlrd', header=None, nrows=8)
    else:
        df = pd.read_excel(file_path, engine='openpyxl', header=None, nrows=8)

    for r in range(8):
        row_vals = []
        for c in range(4):
            val = df.iloc[r, c]
            row_vals.append(f"({r},{c}): {val}")
        print(" | ".join(row_vals))

print_headers('ERP-2025-table10.xls')
print_headers('ERP-2025-table12.xls')

